package com.hkdn.backend.controller;
import com.hkdn.backend.dto.VerificationResponse;import com.hkdn.backend.service.VerificationService;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/public/verify") public class PublicVerificationController {private final VerificationService service;public PublicVerificationController(VerificationService service){this.service=service;}@GetMapping("/certificates/{code}") public VerificationResponse certificate(@PathVariable String code){return service.certificate(code);}@PostMapping(value="/pdf",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public VerificationResponse pdf(@RequestPart("file") MultipartFile file){return service.pdf(file);}}
